                      "    drive.mount('/content/drive')\n",
                      '\n',
                      "DRIVE = Path(f'/content/drive/MyDrive/{DRIVE_PROJECT_FOLDER}')\n",
                      '\n',
                      '# Ghi trực tiếp bản eval_masked_metrics.py mới nhất vào môi trường Colab\n',
                      "eval_script = Path('/content/project/scripts/eval_masked_metrics.py')\n",
                      'eval_script.parent.mkdir(parents=True, exist_ok=True)\n',
                      'eval_script.write_text(\'"""Evaluate Nerfstudio models with strict foreground-mask support and '
                      'Masked LPIPS.\\n\\nStandard `ns-eval` evaluates against the RAW camera frames where the '
                      'background\\n(floor tiles, walls, room) is present. Because the models were trained with '
                      'foreground\\nmasks (which ignores background rays and renders solid black/background outside '
                      'the mask),\\nevaluating the full frame compares black background against bright room '
                      'lighting,\\nartificially collapsing PSNR regardless of model quality.\\n\\nThis script '
                      'evaluates:\\n1. `masked_psnr` (Masked-PSNR): Both Prediction and Ground Truth have background '
                      "zeroed out (black).\\n2. `fg_psnr` (FG-PSNR): Evaluated strictly inside the object\\'s "
                      'foreground mask pixels.\\n3. `masked_ssim`: Structural similarity on foreground cropped '
                      'bounding box.\\n4. `masked_lpips`: Learned Perceptual Image Patch Similarity (AlexNet) computed '
                      'on masked foreground images.\\n"""\\nfrom __future__ import annotations\\nimport '
                      'argparse\\nimport json\\nimport os\\nimport subprocess\\nfrom pathlib import Path\\nimport '
                      'numpy as np\\nimport torch\\nimport cv2\\n\\nos.environ["TORCH_FORCE_NO_WEIGHTS_ONLY_LOAD"] = '
                      '"1"\\nos.environ["QT_QPA_PLATFORM"] = "offscreen"\\n\\n# Ensure PyTorch 2.6+ compatibility for '
                      'nerfstudio checkpoint loading\\ntry:\\n    import importlib.util\\n    spec = '
                      'importlib.util.find_spec("nerfstudio")\\n    if spec and spec.origin:\\n        ns_root = '
                      "Path(spec.origin).parent\\n        old = \\'torch.load(load_path, "
                      'map_location="cpu")\\\'\\n        new = \\\'torch.load(load_path, map_location="cpu", '
                      'weights_only=False)\\\'\\n        for rel in ("utils/eval_utils.py", '
                      '"engine/trainer.py"):\\n            p = ns_root / rel\\n            if '
                      'p.exists():\\n                t = p.read_text(encoding="utf-8")\\n                if old in '
                      't:\\n                    p.write_text(t.replace(old, new), encoding="utf-8")\\nexcept '
                      'Exception:\\n    pass\\n\\ntry:\\n    from nerfstudio.utils.eval_utils import eval_setup\\n    '
                      'from nerfstudio.cameras.cameras import Cameras\\n    NERFSTUDIO_AVAILABLE = True\\nexcept '
                      'ImportError:\\n    NERFSTUDIO_AVAILABLE = False\\n\\n\\ndef ensure_dataset_exists(config_path: '
                      'Path) -> None:\\n    """Tự động kiểm tra và giải nén dữ liệu SFM từ Google Drive nếu ổ đĩa '
                      'Colab bị thiếu."""\\n    try:\\n        content = config_path.read_text(encoding="utf-8", '
                      'errors="ignore")\\n        # Tìm đường dẫn data: e.g. '
                      '/content/project/data/processed/box_001/joint_sfm/transforms_*.json\\n        import '
                      're\\n        m = '
                      "re.search(r\\'data:\\\\s*(?:&id\\\\d+\\\\s*)?(?:!!python/object/apply:pathlib\\\\._local\\\\.PosixPath\\\\s*\\\\n\\\\s*-\\\\s*)?([^\\\\n\\\\r]+)\\', "
                      'content)\\n        if not m:\\n            return\\n        data_str = '
                      'm.group(1).strip().strip("\\\'- \\\\"")\\n        data_path = Path(data_str)\\n        if '
                      'data_path.exists():\\n            return\\n        \\n        # Nếu file transforms không tồn '
                      'tại, trích xuất object_id từ đường dẫn\\n        obj_match = '
                      "re.search(r\\'processed/([^/]+)/joint_sfm\\', data_str)\\n        obj_id = obj_match.group(1) "
                      'if obj_match else None\\n        if not obj_id:\\n            # Fallback lấy từ config path: '
                      '06_experiments/<obj_id>/...\\n            parts = config_path.parts\\n            if '
                      '"06_experiments" in parts:\\n                idx = '
                      'parts.index("06_experiments")\\n                if idx + 1 < len(parts):\\n                    '
                      'obj_id = parts[idx + 1]\\n\\n        if not obj_id:\\n            return\\n\\n        '
                      'print(f"⚠️ Dữ liệu SFM tại {data_path} chưa có trên ổ đĩa Colab.")\\n        # Tìm kiếm file '
                      'tar lưu trữ trên Google Drive\\n        drive_roots = [\\n            '
                      'Path("/content/drive/MyDrive/CV3D_Final_Project"),\\n            '
                      'Path("/content/drive/MyDrive")\\n        ]\\n        candidates = []\\n        for dr in '
                      'drive_roots:\\n            candidates.extend([\\n                dr / "05_processed" / '
                      'f"processed_{obj_id}_joint_sfm_v001.tar",\\n                dr / "99_archives" / '
                      'f"processed_{obj_id}_joint_sfm_v001.tar",\\n                dr / '
                      'f"processed_{obj_id}_joint_sfm_v001.tar",\\n            ])\\n\\n        tar_file = next((p for '
                      'p in candidates if p.exists()), None)\\n        if tar_file is not None:\\n            dest_dir '
                      '= data_path.parent.parent # /content/project/data/processed/box_001\\n            print(f"📦 '
                      'Đang tự động giải nén bản lưu COLMAP & Mask từ Drive: {tar_file}...")\\n            '
                      'dest_dir.mkdir(parents=True, exist_ok=True)\\n            subprocess.run(["tar", "-xf", '
                      'str(tar_file), "-C", str(dest_dir.parent)], check=True)\\n            print(f"✅ Đã khôi phục '
                      'thành công dữ liệu vào {dest_dir}!")\\n        else:\\n            print(f"❌ Không tìm thấy '
                      'file lưu trữ tar cho {obj_id} trên Drive!")\\n    except Exception as e:\\n        print(f"⚠️ '
                      'Không thể tự động phục hồi dataset: {e}")\\n\\n\\ndef calculate_psnr(img1: torch.Tensor, img2: '
                      'torch.Tensor, mask: torch.Tensor | None = None) -> float:\\n    """Compute PSNR. If mask is '
                      'provided (boolean or 0/1), compute only over mask."""\\n    if mask is not None:\\n        '
                      'valid = mask.bool()\\n        if valid.sum() == 0:\\n            return 0.0\\n        diff = '
                      '(img1[valid] - img2[valid]) ** 2\\n        mse = torch.mean(diff).item()\\n    else:\\n        '
                      'mse = torch.mean((img1 - img2) ** 2).item()\\n    \\n    if mse <= 0.0:\\n        return '
                      '100.0\\n    return float(-10.0 * np.log10(mse))\\n\\n\\ndef calculate_ssim(img1: np.ndarray, '
                      'img2: np.ndarray) -> float:\\n    """Calculate SSIM on 0-255 uint8 images using OpenCV or '
                      'skimage."""\\n    try:\\n        from skimage.metrics import structural_similarity as '
                      'ssim\\n        return float(ssim(img1, img2, channel_axis=2, data_range=255))\\n    except '
                      'ImportError:\\n        C1 = (0.01 * 255) ** 2\\n        C2 = (0.03 * 255) ** 2\\n        y1 = '
                      'cv2.cvtColor(img1, cv2.COLOR_RGB2GRAY).astype(np.float64)\\n        y2 = cv2.cvtColor(img2, '
                      'cv2.COLOR_RGB2GRAY).astype(np.float64)\\n        mu1 = cv2.GaussianBlur(y1, (11, 11), '
                      '1.5)\\n        mu2 = cv2.GaussianBlur(y2, (11, 11), 1.5)\\n        sigma1_sq = '
                      'cv2.GaussianBlur(y1 ** 2, (11, 11), 1.5) - mu1 ** 2\\n        sigma2_sq = cv2.GaussianBlur(y2 '
                      '** 2, (11, 11), 1.5) - mu2 ** 2\\n        sigma12 = cv2.GaussianBlur(y1 * y2, (11, 11), 1.5) - '
                      'mu1 * mu2\\n        ssim_map = ((2 * mu1 * mu2 + C1) * (2 * sigma12 + C2)) / ((mu1 ** 2 + mu2 '
                      '** 2 + C1) * (sigma1_sq + sigma2_sq + C2))\\n        return '
                      'float(np.mean(ssim_map))\\n\\n\\ndef init_lpips_fn(device: torch.device):\\n    """Khởi tạo '
                      'metric LPIPS (AlexNet) bằng torchmetrics hoặc thư viện lpips."""\\n    try:\\n        from '
                      'torchmetrics.image.lpip import LearnedPerceptualImagePatchSimilarity\\n        lpips_metric = '
                      'LearnedPerceptualImagePatchSimilarity(net_type="alex", normalize=True).to(device)\\n        '
                      'return lambda p, g: lpips_metric(p, g).item()\\n    except Exception:\\n        pass\\n    '
                      'try:\\n        from torchmetrics.functional.image.lpips import '
                      'learned_perceptual_image_patch_similarity\\n        return lambda p, g: '
                      'float(learned_perceptual_image_patch_similarity(p, g, net_type="alex", '
                      'normalize=True).item())\\n    except Exception:\\n        pass\\n    try:\\n        import '
                      'lpips\\n        loss_fn = lpips.LPIPS(net="alex").to(device)\\n        return lambda p, g: '
                      'float(loss_fn(p * 2.0 - 1.0, g * 2.0 - 1.0).item())\\n    except Exception:\\n        '
                      'pass\\n    return None\\n\\n\\ndef evaluate_config(config_path: Path, output_json: Path | None '
                      '= None, save_renders: bool = False) -> dict:\\n    if not NERFSTUDIO_AVAILABLE:\\n        raise '
                      'SystemExit("nerfstudio is not installed in the active Python environment.")\\n\\n    # Đảm bảo '
                      'dữ liệu test/mask đã sẵn sàng trên đĩa cục bộ\\n    ensure_dataset_exists(config_path)\\n\\n    '
                      'print(f"Loading pipeline from {config_path}...")\\n    _, pipeline, _, _ = '
                      'eval_setup(config_path, eval_num_rays_per_chunk=None, test_mode="test")\\n    '
                      'pipeline.model.eval()\\n\\n    dataset = pipeline.datamanager.eval_dataset\\n    print(f"Loaded '
                      'evaluation dataset with {len(dataset)} held-out frames.")\\n\\n    device = '
                      'pipeline.device\\n    lpips_fn = init_lpips_fn(device)\\n    if lpips_fn is not None:\\n        '
                      'print("✅ Đã kích hoạt Masked LPIPS (AlexNet Perceptual Metric).")\\n    else:\\n        '
                      'print("ℹ️ Không tìm thấy torchmetrics/lpips, LPIPS sẽ hiển thị N/A.")\\n\\n    '
                      'results_per_frame = []\\n    fg_psnrs = []\\n    masked_psnrs = []\\n    unmasked_psnrs = '
                      '[]\\n    ssims = []\\n    lpips_list = []\\n\\n    render_dir = config_path.parent / '
                      '"eval_masked_renders"\\n    if save_renders:\\n        render_dir.mkdir(parents=True, '
                      'exist_ok=True)\\n\\n    with torch.no_grad():\\n        for i in '
                      'range(len(dataset)):\\n            # 1. Render novel view từ model đã học\\n            camera '
                      '= dataset.cameras[i:i+1].to(device)\\n            outputs = '
                      'pipeline.model.get_outputs_for_camera(camera)\\n            pred_rgb = outputs["rgb"] # (H, W, '
                      '3) in [0, 1]\\n            if pred_rgb.ndim == 4:\\n                pred_rgb = '
                      'pred_rgb.squeeze(0)\\n\\n            # 2. Lấy ảnh Ground Truth\\n            batch = '
                      'dataset.get_data(i)\\n            gt_rgb = batch["image"].to(device)\\n            if '
                      'gt_rgb.ndim == 4:\\n                gt_rgb = gt_rgb.squeeze(0)\\n\\n            # Khớp kích '
                      'thước ảnh nếu có chênh lệch tỷ lệ\\n            if pred_rgb.shape[:2] != '
                      'gt_rgb.shape[:2]:\\n                pred_rgb = '
                      'torch.nn.functional.interpolate(\\n                    pred_rgb.permute(2, 0, '
                      '1).unsqueeze(0),\\n                    size=gt_rgb.shape[:2],\\n                    '
                      'mode="bilinear"\\n                ).squeeze(0).permute(1, 2, 0)\\n\\n            # 3. Lấy '
                      'mask\\n            mask = None\\n            if "mask" in batch and batch["mask"] is not '
                      'None:\\n                m = batch["mask"]\\n                if isinstance(m, '
                      'torch.Tensor):\\n                    mask = m.to(device)\\n                '
                      'else:\\n                    mask = torch.from_numpy(m).to(device)\\n                if '
                      'mask.ndim == 2:\\n                    mask = mask.unsqueeze(-1)\\n\\n            # Nếu batch '
                      'không có mask trực tiếp, nạp từ file ảnh mask\\n            if mask is None and '
                      'hasattr(dataset, "image_filenames"):\\n                img_path = '
                      'Path(dataset.image_filenames[i])\\n                possible_masks = [\\n                    '
                      'img_path.parent.parent / img_path.parent.name.replace("images", "masks") / '
                      'f"{img_path.stem}.png",\\n                    img_path.parent.parent / "masks" / '
                      'f"{img_path.stem}.png",\\n                    img_path.parent.parent / "masks_2" / '
                      'f"{img_path.stem}.png",\\n                    img_path.parent.parent / "masks_4" / '
                      'f"{img_path.stem}.png",\\n                ]\\n                mask_file = next((p for p in '
                      'possible_masks if p.is_file()), None)\\n                if mask_file is not '
                      'None:\\n                    m_cv = cv2.imread(str(mask_file), '
                      'cv2.IMREAD_GRAYSCALE)\\n                    if m_cv is not None:\\n                        if '
                      'm_cv.shape[:2] != gt_rgb.shape[:2]:\\n                            m_cv = cv2.resize(m_cv, '
                      '(gt_rgb.shape[1], gt_rgb.shape[0]), interpolation=cv2.INTER_NEAREST)\\n                        '
                      'mask = (torch.from_numpy(m_cv).to(device) >= 128).unsqueeze(-1)\\n\\n            if mask is '
                      'None:\\n                mask = torch.ones_like(gt_rgb[:, :, :1], '
                      'dtype=torch.bool)\\n            else:\\n                mask = (mask > 0.5)\\n\\n            '
                      'mask_bool = mask\\n            mask_3c = mask_bool.expand_as(gt_rgb)\\n\\n            # 1. '
                      'Unmasked PSNR (tiêu chuẩn ns-eval)\\n            unmasked_psnr = calculate_psnr(pred_rgb, '
                      'gt_rgb, None)\\n            \\n            # 2. Foreground-only PSNR (chỉ tính trên các pixel '
                      'thuộc vật thể)\\n            fg_psnr = calculate_psnr(pred_rgb, gt_rgb, '
                      'mask_3c)\\n\\n            # 3. Masked Full-Frame PSNR (cả GT và Pred đều cắt nền về đen '
                      '[0,0,0])\\n            pred_masked = torch.where(mask_3c, pred_rgb, '
                      'torch.zeros_like(pred_rgb))\\n            gt_masked = torch.where(mask_3c, gt_rgb, '
                      'torch.zeros_like(gt_rgb))\\n            masked_full_psnr = calculate_psnr(pred_masked, '
                      'gt_masked, None)\\n\\n            # 4. SSIM trên bounding box của vật thể\\n            pred_np '
                      '= (pred_masked.cpu().numpy() * 255).clip(0, 255).astype(np.uint8)\\n            gt_np = '
                      '(gt_masked.cpu().numpy() * 255).clip(0, 255).astype(np.uint8)\\n            mask_np = '
                      'mask_bool.squeeze().cpu().numpy().astype(np.uint8)\\n\\n            y_indices, x_indices = '
                      'np.where(mask_np > 0)\\n            if len(y_indices) > 0:\\n                y0, y1 = max(0, '
                      'y_indices.min() - 10), min(mask_np.shape[0], y_indices.max() + 10)\\n                x0, x1 = '
                      'max(0, x_indices.min() - 10), min(mask_np.shape[1], x_indices.max() + 10)\\n                '
                      'ssim_val = calculate_ssim(pred_np[y0:y1, x0:x1], gt_np[y0:y1, x0:x1])\\n            '
                      'else:\\n                ssim_val = calculate_ssim(pred_np, gt_np)\\n\\n            # 5. Masked '
                      'LPIPS (So sánh cảm nhận trực quan trên vùng vật thể đã cắt đen nền)\\n            lpips_val = '
                      'None\\n            if lpips_fn is not None:\\n                try:\\n                    p_chw '
                      '= pred_masked.permute(2, 0, 1).unsqueeze(0).clamp(0.0, 1.0)\\n                    g_chw = '
                      'gt_masked.permute(2, 0, 1).unsqueeze(0).clamp(0.0, 1.0)\\n                    lpips_val = '
                      'lpips_fn(p_chw, g_chw)\\n                    lpips_list.append(lpips_val)\\n                '
                      'except Exception:\\n                    pass\\n\\n            '
                      'fg_psnrs.append(fg_psnr)\\n            masked_psnrs.append(masked_full_psnr)\\n            '
                      'unmasked_psnrs.append(unmasked_psnr)\\n            ssims.append(ssim_val)\\n\\n            '
                      'results_per_frame.append({\\n                "frame_idx": i,\\n                "fg_psnr": '
                      'round(fg_psnr, 2),\\n                "masked_psnr": round(masked_full_psnr, '
                      '2),\\n                "ssim": round(ssim_val, 4),\\n                "lpips": round(lpips_val, '
                      '4) if lpips_val is not None else None\\n            })\\n\\n            if save_renders and i < '
                      '5:\\n                # Lưu ảnh so sánh 2 cột: GT Masked | Pred Masked\\n                '
                      'side_by_side = np.hstack([\\n                    cv2.cvtColor(gt_np, '
                      'cv2.COLOR_RGB2BGR),\\n                    cv2.cvtColor(pred_np, '
                      'cv2.COLOR_RGB2BGR)\\n                ])\\n                cv2.imwrite(str(render_dir / '
                      'f"compare_frame_{i:04d}.jpg"), side_by_side)\\n\\n    mean_lpips = '
                      'round(float(np.mean(lpips_list)), 4) if lpips_list else None\\n    summary = {\\n        '
                      '"metrics": {\\n            "masked_psnr_mean": round(float(np.mean(masked_psnrs)), '
                      '2),\\n            "fg_psnr_mean": round(float(np.mean(fg_psnrs)), 2),\\n            '
                      '"masked_ssim_mean": round(float(np.mean(ssims)), 4),\\n            "masked_lpips_mean": '
                      'mean_lpips,\\n            # Tương thích ngược với các bản đọc cũ\\n            '
                      '"foreground_only_psnr_mean": round(float(np.mean(fg_psnrs)), 2),\\n            '
                      '"masked_full_psnr_mean": round(float(np.mean(masked_psnrs)), 2),\\n            '
                      '"unmasked_raw_psnr_mean": round(float(np.mean(unmasked_psnrs)), 2),\\n            "ssim_mean": '
                      'round(float(np.mean(ssims)), 4),\\n        },\\n        "num_frames_evaluated": '
                      'len(dataset)\\n    }\\n\\n    print("\\\\n" + "=" * 60)\\n    print("📊 KẾT QUẢ ĐÁNH GIÁ MASKED '
                      'METRICS (FOREGROUND-ONLY)")\\n    print("=" * 60)\\n    print(f"🎯 Masked-PSNR (Cắt đen nền cả '
                      '2):     {summary[\\\'metrics\\\'][\\\'masked_psnr_mean\\\']} dB")\\n    print(f"🔍 FG-PSNR (Chỉ '
                      'tính pixel vật thể):   {summary[\\\'metrics\\\'][\\\'fg_psnr_mean\\\']} dB")\\n    print(f"✨ '
                      'Masked SSIM:                         '
                      '{summary[\\\'metrics\\\'][\\\'masked_ssim_mean\\\']}")\\n    lpips_display = '
                      'f"{mean_lpips:.4f}" if mean_lpips is not None else "N/A"\\n    print(f"👁️ Masked LPIPS (AlexNet '
                      'Perceptual):   {lpips_display}")\\n    print("=" * 60)\\n\\n    out_path = output_json or '
                      '(config_path.parent / "test_metrics_masked.json")\\n    out_path.write_text(json.dumps(summary, '
                      'indent=2), encoding="utf-8")\\n    print(f"Wrote detailed metrics to {out_path}")\\n\\n    '
                      'compat_path = config_path.parent / "masked_eval_metrics.json"\\n    if compat_path != '
                      'out_path:\\n        compat_path.write_text(json.dumps(summary, indent=2), '
                      'encoding="utf-8")\\n\\n    return summary\\n\\n\\ndef main() -> None:\\n    parser = '
                      'argparse.ArgumentParser(description="Evaluate Nerfstudio checkpoint with foreground masking and '
                      'LPIPS.")\\n    parser.add_argument("--config", "--config-path", dest="config", type=Path, '
                      'default=None, help="Path to config.yml")\\n    parser.add_argument("--output-json", type=Path, '
                      'default=None, help="Where to save metrics JSON")\\n    parser.add_argument("--save-renders", '
                      'action="store_true", help="Save side-by-side comparison renders")\\n    '
                      'parser.add_argument("--object-id", type=str, default=None, help="Evaluate all experiments for '
                      'an object (e.g. box_001)")\\n    parser.add_argument("--all-objects", action="store_true", '
                      'help="Evaluate all objects in 06_experiments")\\n    parser.add_argument("--drive-dir", '
                      'type=Path, default=Path("/content/drive/MyDrive/CV3D_Final_Project"), help="Google Drive base '
                      'path")\\n    args = parser.parse_args()\\n\\n    if args.config is not None:\\n        '
                      'evaluate_config(args.config, args.output_json, args.save_renders)\\n    elif args.object_id or '
                      "args.all_objects:\\n        objs = [\\'box_001\\', \\'basket_001\\', \\'figure_001\\', "
                      "\\'stuff_toy_001\\'] if args.all_objects else [args.object_id]\\n        for obj in "
                      "objs:\\n            obj_exp = args.drive_dir / \\'06_experiments\\' / obj\\n            if not "
                      'obj_exp.exists():\\n                continue\\n            cfgs = '
                      'sorted(obj_exp.glob(\\\'**/config.yml\\\'))\\n            print(f"Found {len(cfgs)} configs for '
                      '{obj} in {obj_exp}")\\n            for cfg in cfgs:\\n                eval_out = cfg.parent / '
                      "\\'test_metrics_masked.json\\'\\n                evaluate_config(cfg, eval_out, "
                      'args.save_renders)\\n    else:\\n        parser.print_help()\\n\\n\\nif __name__ == '
                      '"__main__":\\n    main()\\n\', encoding=\'utf-8\')\n',
                      "print('✅ Đã nạp thành công eval_masked_metrics.py vào /content/project/scripts/')\n",
                      '\n',
                      "target_objs = ['box_001', 'basket_001', 'figure_001', 'stuff_toy_001'] if TARGET_OBJECT == "
                      "'ALL' else [TARGET_OBJECT]\n",
                      '\n',
                      'for obj in target_objs:\n',
                      "    exp_base = DRIVE / '06_experiments' / obj\n",
                      '    if not exp_base.exists():\n',
                      '        continue\n',
                      '\n',
                      '    # 1. Tự động kiểm tra và giải nén dữ liệu COLMAP & ảnh test cho obj nếu chưa có trên ổ đĩa '
                      'Colab\n',
                      "    obj_sfm_dir = Path(f'/content/project/data/processed/{obj}/joint_sfm')\n",
                      "    if not (obj_sfm_dir / 'transforms_orbit_views_100.json').exists():\n",
                      '        tar_candidates = [\n',
                      "            DRIVE / '05_processed' / f'processed_{obj}_joint_sfm_v001.tar',\n",
                      "            DRIVE / '99_archives' / f'processed_{obj}_joint_sfm_v001.tar',\n",
                      '        ]\n',
                      '        tar_file = next((p for p in tar_candidates if p.exists()), None)\n',
                      '        if tar_file is not None:\n',
                      "            print(f'📦 Đang tự động khôi phục dữ liệu COLMAP & ảnh test cho {obj} từ Drive "
                      "({tar_file.name})...')\n",
                      '            obj_sfm_dir.parent.mkdir(parents=True, exist_ok=True)\n',
                      "            subprocess.run(['tar', '-xf', str(tar_file), '-C', str(obj_sfm_dir.parent)], "
                      'check=True)\n',
                      "            print(f'✅ Đã khôi phục hoàn tất vào {obj_sfm_dir}!')\n",
                      '        else:\n',
